  teamTransfers: (groupId) => `/api/v1/team/groups/${encodeURIComponent(groupId)}/transfers`,
  teamCheckoutSessions: (groupId) => `/api/v1/team/groups/${encodeURIComponent(groupId)}/checkout-sessions`,
