function generationErrorReply(r) {
  const structured = {
    ok: false,
    error: r.error,
    error_code: r.error_code ?? "unknown",
    ...r.user_message ? { user_message: r.user_message } : {},
    ...r.failure_presentation ? { failure_presentation: r.failure_presentation } : {},
    ...r.recovery_handle ? { recovery_handle: r.recovery_handle } : {},
    ...r.billing ? { billing: r.billing } : {}
  };
  const isNonTerminal = r.failure_presentation === "recoverable" || r.failure_presentation === "status_unknown";
  const response = isNonTerminal ? { ...structured, do_not_resubmit: true } : structured;
  const reply = {
    structuredContent: response,
    content: [{ type: "text", text: JSON.stringify(response) }]
  };
  return isNonTerminal ? { ...reply, isError: false } : { ...reply, isError: true };
}
function generationUnknownReply(msg) {
  return generationErrorReply({
    ok: false,
    error: msg,
    error_code: "unknown",
    failure_presentation: "status_unknown"
  });
}

