function registerHubGenerateAudioMusic(server2, gw, region2 = "domestic") {
  server2.registerTool(
    "generate_audio_music",
    {
      confirmable: true,
      vendorParamHints: buildVendorParamHints("audio", region2),
      description: [
        "Generate music with Official Music 3.0.",
        "Artifact cardinality: one invocation returns one final track. The prompt/lyrics describe a single track; multiple deliverables must be represented as separate asset tasks/tool calls.",
        "",
        'Model selection: call `hub_list_capabilities({modality:"audio.music"})` if you need the canonical manifest. Use `vendor=official, model_id=music-3.0` for BGM/score/instrumental music and for vocal or lyrics-first songs after lyrics are confirmed.',
        "",
        "Mode selection:",
        "  - vendor=official mode=song: full song WITH vocals. `lyrics` REQUIRED; write lyrics directly or use user-provided lyrics, and have the user confirm before passing them in.",
        "  - vendor=official mode=instrumental: pure background music. `lyrics` ignored."
      ].join("\n"),
      inputSchema: {
        vendor: external_exports.enum(AUDIO_MUSIC_VENDOR_ENUM).optional().default("official").describe("Music vendor. Only official Music 3.0 is supported."),
        model_id: external_exports.enum(["music-3.0"]).optional().describe("Canonical model id from hub_list_capabilities. Defaults by vendor."),
        mode: external_exports.enum(["song", "instrumental"]).describe("song = vocals/music; instrumental = instrumental BGM."),
        prompt: external_exports.string().describe(
          "Single-track style / mood brief for one final artifact. Preserve deliverable topology; separate user-intended outcome units use separate calls."
        ),
        lyrics: external_exports.string().optional().describe(
          "Required when mode=song. Use structure tags like [verse], [chorus], [bridge]. Write lyrics directly or use user-provided lyrics, and confirm with the user before passing in."
        ),
        filename: external_exports.string().describe("Output filename WITHOUT extension.")
      },
      outputSchema: {
        ok: external_exports.boolean(),
        path: external_exports.string().optional(),
        duration: external_exports.number().optional(),
        node_id: external_exports.string().optional(),
        error: external_exports.string().optional(),
        error_code: external_exports.string().optional(),
        user_message: external_exports.string().optional(),
        failure_presentation: GenerateFailurePresentationSchema.optional(),
        recovery_handle: external_exports.string().optional(),
        do_not_resubmit: external_exports.boolean().optional(),
        billing: BillingErrorMetadataSchema.optional()
      }
    },
    async (rawArgs) => {
      const args = rawArgs;
      const vendor = args.vendor ?? "official";
      if (!AUDIO_MUSIC_VENDOR_ENUM.includes(vendor)) {
        return errorReply(`Unsupported music vendor: ${String(vendor)}.`);
      }
      const config2 = AUDIO_MUSIC_VENDOR_CONFIGS[vendor];
      const modelResolved = resolveCapabilityModel({
        type: "audio",
        config: config2,
        region: region2,
        rawModelId: args.model_id,
        modelIdExplicit: args.model_id !== void 0,
        scope: `audio.music vendor=${vendor}`
      });
      const guardModelId = modelResolved.error ? args.model_id ?? config2.defaultModel : modelResolved.modelId;
      const pickerError = await selectedAudioError(gw, MUSIC_VENDOR_SERIES[vendor], guardModelId);
      if (pickerError) return errorReply(pickerError);
      const built = buildMusicParams(args, region2);
      if (built.error) return errorReply(built.error);
      if (!built.backend || !built.modelId || !built.params || !built.sourceToolMode) {
        return errorReply("Internal: music body builder returned incomplete body");
      }
      try {
        const r = await gw.generateMusic({
          backend: built.backend,
          model_id: built.modelId,
          prompt: args.prompt,
          filename: args.filename,
          params: built.params,
          source_tool: `hub_generate_audio_music:${built.sourceToolMode}`
        });
        if (!r.ok) return generationErrorReply(r);
        const structured = {
          ok: true,
          path: r.path,
          duration: r.duration ?? 0,
          ...r.node_id ? { node_id: r.node_id } : {}
        };
        return structuredReply(structured);
      } catch (err) {
        const msg = err instanceof Error ? err.message : String(err);
        return generationUnknownReply(`Error generating music: ${msg}`);
      }
    }
  );
}

