function registerWebMediaTools(server2, gateway2) {
  server2.registerTool(
    "web_media",
    {
      description: 'Inspect or download public web media that the user is authorized to access with yt-dlp. Use type="inspect" to read metadata, formats, subtitles, and thumbnails without downloading. Downloaded video, audio, subtitles, and thumbnails are saved into the current workspace and placed on canvas automatically. For a direct image file URL (for example a Pinterest i.pinimg.com .jpg), prefer hub_canvas_write_node(kind="media") (or hub_canvas_write_media_node on v1); do not use download_thumbnail for a direct file URL or an arbitrary non-yt-dlp web page. Only type and url are required. Do not use for local files or URLs that require login.',
      inputSchema: {
        type: external_exports.enum(OPERATIONS).describe("Operation to perform."),
        url: external_exports.string().url().describe(
          'Public HTTP or HTTPS media page URL for yt-dlp; direct image URLs should go through hub_canvas_write_node(kind="media").'
        ),
        quality: external_exports.enum(["best", "2160p", "1080p", "720p", "480p"]).optional().describe("Video quality ceiling. download_video only; default best."),
        format_id: external_exports.string().min(1).optional().describe("Exact format id returned by inspect. Mutually exclusive with quality."),
        container: external_exports.enum(["mp4", "mkv", "webm", "mp3", "m4a", "wav"]).optional().describe("Output container. Video default mp4; audio default m4a."),
        subtitle_languages: external_exports.array(external_exports.string().min(1)).min(1).optional().describe('Subtitle language codes, for example ["zh-CN", "en"].'),
        subtitle_format: external_exports.enum(["srt", "vtt"]).optional().describe("Subtitle output format. Default srt."),
        include_auto_subtitles: external_exports.boolean().optional().describe("Allow automatic captions when downloading subtitles."),
        playlist_mode: external_exports.enum(["single", "all"]).optional().describe("Download only the addressed item by default, or the bounded playlist."),
        max_items: external_exports.number().int().min(1).max(50).optional().describe('Maximum playlist items. Requires playlist_mode="all"; default 20.'),
        filename: external_exports.string().min(1).optional().describe("Optional output filename without extension."),
        source_node_id: external_exports.string().min(1).optional().describe("Optional canvas source node for a derivation edge.")
      },
      outputSchema: {
        ok: external_exports.boolean(),
        type: external_exports.enum(OPERATIONS),
        metadata: external_exports.record(external_exports.unknown()).optional(),
        assets: external_exports.array(
          external_exports.object({
            kind: external_exports.enum(["video", "audio", "subtitle", "image"]),
            path: external_exports.string()
          })
        ).optional(),
        warnings: external_exports.array(external_exports.string()).optional(),
        error: external_exports.string().optional()
      },
      attachmentOutputPaths: (output) => output.assets?.map((asset) => asset.path) ?? []
    },
    async (args) => {
      const response = args.type === "download_thumbnail" && isDirectImageUrl(args.url) ? await downloadDirectImageUrl(gateway2, args) : await gateway2.webMedia(args);
      return {
        structuredContent: response,
        content: [{ type: "text", text: JSON.stringify(response) }],
        ...response.ok ? {} : { isError: true }
      };
    }
  );
}

